technical-challenge.recommended-solution:
import asyncio
class StatusContext: def __init__(self, conversation_id: str): self.conversation_id = conversation_id self.queue: asyncio.Queue[str] = asyncio.Queue()
def emit(self, message: str): """Called by emit_status() to queue status messages""" self.queue.put_nowait(message)
async def drain_status(self) -> list[str]: """Get all pending status messages without blocking""" messages = [] while not self.queue.empty(): messages.append(self.queue.get_nowait()) return messages

step.code-example:

def format_status_frame(message: str) -> Dict[str, Any]:
    """Format status message as SSE event"""
    return {
        "event": "message",
        "data": json.dumps({"type": "status", "message": message})
    }

from backend.api.status import StatusContext, emit_status
# At start of stream_generator(): status_queue = asyncio.Queue()
def status_callback(message: str): """Callback that queues status messages for emission""" status_queue.put_nowait(message)
async with StatusContext(conversation_id, status_callback): # Emit initial thinking status emit_status("Annie is thinking...")
# Existing streaming logic... async for event in llm_client.stream_chat_completion(...): # Before yielding each event, drain status queue while not status_queue.empty(): status_msg = status_queue.get_nowait() yield format_status_frame(status_msg)
yield { "event": "message", "data": json.dumps(event) }
